INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'universe', 'n.', '/ˈjuːnɪvɜːs/', '宇宙;天地万物', 'Scientists want to learn how the universe began.', '科学家想了解宇宙是如何开始的。', 'Space Exploration', 1, 0, 'senior', 'wordlist', 'required3', 'U4', 'explore the universe', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'mystery', 'n.', '/ˈmɪstri/', '神秘事物;谜', 'Space is full of mysteries that we still cannot explain.', '太空充满了我们仍无法解释的谜团。', 'Space Exploration', 2, 0, 'senior', 'wordlist', 'required3', 'U4', 'solve a mystery', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'desire', 'n./v.', '/dɪˈzaɪə(r)/', '渴望;欲望;期望', 'The desire to understand space drives many scientists.', '理解太空的渴望驱使着许多科学家。', 'Space Exploration', 3, 0, 'senior', 'wordlist', 'required3', 'U4', 'the desire to explore', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'determined', 'adj.', '/dɪˈtɜːmɪnd/', '有决心的;意志坚定的', 'Some scientists were determined to help humans reach space.', '一些科学家下定决心帮助人类抵达太空。', 'Space Exploration', 4, 0, 'senior', 'wordlist', 'required3', 'U4', 'be determined to do', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'determine', 'v.', '/dɪˈtɜːmɪn/', '查明;确定;决定', 'Engineers worked hard to determine the cause of the accident.', '工程师们努力查明事故的原因。', 'Space Exploration', 5, 0, 'senior', 'wordlist', 'required3', 'U4', 'determine the cause', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'launch', 'v./n.', '/lɔːntʃ/', '发射;发起;上市', 'The USSR was the first country to launch a satellite into space.', '苏联是第一个把卫星发射到太空的国家。', 'Space Exploration', 6, 0, 'senior', 'wordlist', 'required3', 'U4', 'launch a rocket', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'satellite', 'n.', '/ˈsætəlaɪt/', '人造卫星;卫星', 'A weather satellite records data about the wind and the rain.', '气象卫星记录关于风和雨的数据。', 'Space Exploration', 7, 0, 'senior', 'wordlist', 'required3', 'U4', 'a weather satellite', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'orbit', 'n./v.', '/ˈɔːbɪt/', '(运行的)轨道;沿轨道运行', 'The spacecraft will orbit Earth for several days.', '这艘航天器将绕地球运行数天。', 'Space Exploration', 8, 0, 'senior', 'wordlist', 'required3', 'U4', 'orbit Earth', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'spacecraft', 'n.', '/ˈspeɪskrɑːft/', '航天器;宇宙飞船', 'Yang Liwei orbited Earth in the Shenzhou 5 spacecraft.', '杨利伟乘神舟五号飞船绕地球运行。', 'Space Exploration', 9, 0, 'senior', 'wordlist', 'required3', 'U4', 'a manned spacecraft', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'rocket', 'n.', '/ˈrɒkɪt/', '火箭;火箭弹', 'Scientists made rockets powerful enough to escape Earth''s gravity.', '科学家造出了强大到足以摆脱地球引力的火箭。', 'Space Exploration', 10, 0, 'senior', 'wordlist', 'required3', 'U4', 'build a rocket', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'gravity', 'n.', '/ˈɡrævəti/', '重力;引力', 'Because there is little gravity in space, astronauts float around.', '由于太空里几乎没有重力,宇航员会四处漂浮。', 'Space Exploration', 11, 0, 'senior', 'wordlist', 'required3', 'U4', 'escape gravity', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'frontier', 'n.', '/ˈfrʌntɪə(r)/', '边界;边远地区;(知识的)前沿', 'Many people call space the final frontier for humankind.', '许多人把太空称作人类最后的边疆。', 'Space Exploration', 12, 0, 'senior', 'wordlist', 'required3', 'U4', 'the final frontier', '美音 /frʌnˈtɪr/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'mankind', 'n.', '/mænˈkaɪnd/', '人类', 'The moon landing was a giant leap for mankind.', '登月是人类的一大飞跃。', 'Space Exploration', 13, 0, 'senior', 'wordlist', 'required3', 'U4', 'a leap for mankind', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'leap', 'n./v.', '/liːp/', '跳跃;剧增;飞跃', 'Armstrong called his step a giant leap for all people.', '阿姆斯特朗把他的这一步称为全人类的一大飞跃。', 'Space Exploration', 14, 0, 'senior', 'wordlist', 'required3', 'U4', 'a giant leap', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'giant', 'adj./n.', '/ˈdʒaɪənt/', '巨大的;伟大的;巨人', 'Landing on the moon was a giant step in space exploration.', '登月是太空探索中的一大步。', 'Space Exploration', 15, 0, 'senior', 'wordlist', 'required3', 'U4', 'a giant step', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'globe', 'n.', '/ɡləʊb/', '地球;世界;地球仪', 'Countries around the globe are spending money on space missions.', '全球各国都在为太空任务投入资金。', 'Space Exploration', 16, 0, 'senior', 'wordlist', 'required3', 'U4', 'around the globe', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'data', 'n.', '/ˈdeɪtə/', '资料;数据', 'Voyager 1 still transmits data back to Earth today.', '旅行者一号至今仍向地球传回数据。', 'Space Exploration', 17, 0, 'senior', 'wordlist', 'required3', 'U4', 'collect data', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'transmit', 'v.', '/trænzˈmɪt/', '传输;发送', 'The satellite will transmit pictures of the storm to scientists.', '这颗卫星会把风暴的图像传给科学家。', 'Space Exploration', 18, 0, 'senior', 'wordlist', 'required3', 'U4', 'transmit data', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'signal', 'v./n.', '/ˈsɪɡnəl/', '标志着;发信号;信号;标志', 'The new space lab signalled one more step in China''s plan.', '这个新的太空实验室标志着中国计划又向前迈进一步。', 'Space Exploration', 19, 0, 'senior', 'wordlist', 'required3', 'U4', 'send a signal', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'dock', 'v./n.', '/dɒk/', '(航天器)对接;进港;码头', 'Tianzhou 1 was sent up to dock with the space lab.', '天舟一号被送上去与太空实验室对接。', 'Space Exploration', 20, 0, 'senior', 'wordlist', 'required3', 'U4', 'dock with the lab', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'independently', 'adv.', '/ˌɪndɪˈpendəntli/', '独立地;自立地', 'China became the third country to send humans into space independently.', '中国成为第三个独立把人送入太空的国家。', 'Space Exploration', 21, 0, 'senior', 'wordlist', 'required3', 'U4', 'act independently', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'independent', 'adj.', '/ˌɪndɪˈpendənt/', '独立的;自立的', 'Each country wants an independent space programme of its own.', '每个国家都想拥有自己独立的太空计划。', 'Space Exploration', 22, 0, 'senior', 'wordlist', 'required3', 'U4', 'an independent programme', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'facility', 'n.', '/fəˈsɪləti/', '设施;设备', 'Astronauts use special facilities to live and work in space.', '宇航员使用特殊设施在太空生活和工作。', 'Space Exploration', 23, 0, 'senior', 'wordlist', 'required3', 'U4', 'training facilities', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'procedure', 'n.', '/prəˈsiːdʒə(r)/', '程序;步骤;手续', 'The selection procedure for astronauts is long and difficult.', '宇航员的选拔程序漫长而艰难。', 'Space Exploration', 24, 0, 'senior', 'wordlist', 'required3', 'U4', 'the selection procedure', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'intelligent', 'adj.', '/ɪnˈtelɪdʒənt/', '有智慧的;聪明的', 'You must be intelligent enough to get a related college degree.', '你必须足够聪明才能拿到相关的大学学位。', 'Space Exploration', 25, 0, 'senior', 'wordlist', 'required3', 'U4', 'intelligent enough', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'mental', 'adj.', '/ˈmentl/', '精神的;思想的;心理的', 'Astronauts do a lot of mental and physical training.', '宇航员要进行大量的心理和身体训练。', 'Space Exploration', 26, 0, 'senior', 'wordlist', 'required3', 'U4', 'mental training', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'muscle', 'n.', '/ˈmʌsl/', '肌肉;力量', 'In space, an astronaut''s muscles can get very weak.', '在太空中,宇航员的肌肉会变得很虚弱。', 'Space Exploration', 27, 0, 'senior', 'wordlist', 'required3', 'U4', 'weak muscles', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'float', 'v.', '/fləʊt/', '漂浮;漂流', 'Without gravity, everything would float off into the air.', '没有重力,一切都会漂浮到空中。', 'Space Exploration', 28, 0, 'senior', 'wordlist', 'required3', 'U4', 'float around', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'oxygen', 'n.', '/ˈɒksɪdʒən/', '氧;氧气', 'The accident caused a loss of oxygen on board.', '这次事故导致舱内氧气流失。', 'Space Exploration', 29, 0, 'senior', 'wordlist', 'required3', 'U4', 'a loss of oxygen', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'recycle', 'v.', '/ˌriːˈsaɪkl/', '回收利用;再利用', 'Astronauts collect dirty water so as to recycle it.', '宇航员收集脏水以便回收利用。', 'Space Exploration', 30, 0, 'senior', 'wordlist', 'required3', 'U4', 'recycle water', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'resource', 'n.', '/rɪˈsɔːs/', '资源;财力;物力', 'Pictures of Earth made people realise that our resources are limited.', '地球的照片让人们意识到我们的资源是有限的。', 'Space Exploration', 31, 0, 'senior', 'wordlist', 'required3', 'U4', 'limited resources', '美音 /ˈriːsɔːrs/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'limited', 'adj.', '/ˈlɪmɪtɪd/', '有限的', 'The resources on Earth are limited and may one day run out.', '地球上的资源是有限的,有朝一日可能会耗尽。', 'Space Exploration', 32, 0, 'senior', 'wordlist', 'required3', 'U4', 'limited resources', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'sufficient', 'adj.', '/səˈfɪʃnt/', '足够的;充足的', 'A long journey needs sufficient food and water for the crew.', '漫长的旅程需要为机组人员准备足够的食物和水。', 'Space Exploration', 33, 0, 'senior', 'wordlist', 'required3', 'U4', 'sufficient food', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'fatal', 'adj.', '/ˈfeɪtl/', '致命的;灾难性的', 'We should solve problems like pollution and fatal diseases first.', '我们应当先解决污染和致命疾病等问题。', 'Space Exploration', 34, 0, 'senior', 'wordlist', 'required3', 'U4', 'a fatal disease', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'shallow', 'adj.', '/ˈʃæləʊ/', '肤浅的;浅的', 'Others feel that this is a shallow view of space exploration.', '另一些人觉得这是对太空探索的肤浅看法。', 'Space Exploration', 35, 0, 'senior', 'wordlist', 'required3', 'U4', 'a shallow view', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'monitor', 'n./v.', '/ˈmɒnɪtə(r)/', '监测仪;监视器;监测', 'Space science has helped companies make better heart monitors.', '太空科学帮助公司造出了更好的心脏监测仪。', 'Space Exploration', 36, 0, 'senior', 'wordlist', 'required3', 'U4', 'heart monitors', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'current', 'adj./n.', '/ˈkʌrənt/', '当前的;现在的;水流;电流', 'Using current technology, a trip to Mars would take years.', '用目前的技术,一趟火星之旅要花上数年。', 'Space Exploration', 37, 0, 'senior', 'wordlist', 'required3', 'U4', 'current technology', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'figure out', 'phr.', '/ˈfɪɡə(r) aʊt/', '弄懂;弄清楚', 'Will scientists figure out a way to store food for the journey?', '科学家能想出办法为这趟旅程储存食物吗?', 'Space Exploration', 38, 0, 'senior', 'wordlist', 'required3', 'U4', 'figure out a way', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'carry on', 'phr.', '/ˈkæri ɒn/', '继续;坚持', 'People believe in the importance of carrying on space exploration.', '人们相信继续进行太空探索的重要性。', 'Space Exploration', 39, 0, 'senior', 'wordlist', 'required3', 'U4', 'carry on the work', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'result in', 'phr.', '/rɪˈzʌlt ɪn/', '导致;造成', 'A small mistake during a launch can result in a serious accident.', '发射过程中的一个小错误可能导致严重事故。', 'Space Exploration', 40, 0, 'senior', 'wordlist', 'required3', 'U4', 'result in an accident', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'run out', 'phr.', '/rʌn aʊt/', '用完;耗尽', 'If the resources on Earth run out, we may need a new home.', '如果地球上的资源耗尽,我们也许需要一个新家园。', 'Space Exploration', 41, 0, 'senior', 'wordlist', 'required3', 'U4', 'run out of fuel', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'regularly', 'adv.', '/ˈreɡjələli/', '经常;定期地', 'Astronauts must exercise regularly to stay healthy in space.', '宇航员必须定期锻炼才能在太空保持健康。', 'Space Exploration', 42, 0, 'senior', 'wordlist', 'required3', 'U4', 'exercise regularly', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'regular', 'adj.', '/ˈreɡjələ(r)/', '定期的;经常的;正常的', 'Regular exercise helps astronauts keep their muscles strong.', '定期锻炼帮助宇航员保持肌肉强健。', 'Space Exploration', 43, 0, 'senior', 'wordlist', 'required3', 'U4', 'regular exercise', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'vehicle', 'n.', '/ˈviːəkl/', '交通工具;车辆', 'They made vehicles to carry brave people into space.', '他们制造出运送勇敢者进入太空的飞行器。', 'Space Exploration', 44, 0, 'senior', 'wordlist', 'required3', 'U4', 'a lunar vehicle', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'pattern', 'n.', '/ˈpætn/', '模式;图案;规律', 'Satellites record data on land and weather patterns.', '卫星记录关于陆地和天气模式的数据。', 'Space Exploration', 45, 0, 'senior', 'wordlist', 'required3', 'U4', 'weather patterns', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'otherwise', 'adv.', '/ˈʌðəwaɪz/', '否则;要不然', 'Astronauts stick everything down; otherwise it would float off.', '宇航员把一切都固定住,否则东西会漂走。', 'Space Exploration', 46, 0, 'senior', 'wordlist', 'required3', 'U4', 'stick it down, otherwise…', NULL);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('r3u4.01', '①不定式作目的状语(to do / in order to do / so as to do)', 'A2', 10, '必修三 U4 — 表示动作的目的,用 to do(也可 in order to / so as to + do)。回答 why、强调''为了……'',不可用 doing/done。', 1, 'required3', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('r3u4.02', '②不定式作后置定语(the first person to do / something to eat)', 'A2', 10, '必修三 U4 — 不定式放在名词后修饰它,表示''要做、将做''的动作,如 the first person to do、a lot of work to do、the best way to do、something to eat。', 2, 'required3', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('r3u4.03', '③不定式作宾语/宾补/主语(want/decide to do · ask sb to do · It is … to do),与 doing 对照', 'A2', 10, '必修三 U4 — want/decide/hope/need 等后接 to do;ask/tell/allow/want sb to do 作宾补;It is … to do 作真主语。由动词搭配决定用 to do 还是 doing。', 3, 'required3', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U4' AND code='r3u4.01'), 'Scientists make special vehicles ____ brave people into space.', 'to carry', 'carrying', 'carried', 'carry', 'A', '表目的''为了运送''→ 不定式 to carry。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U4' AND code='r3u4.01'), 'An astronaut needs to be calm ____ in space safely.', 'working', 'to work', 'worked', 'work', 'B', '表目的''为了在太空工作''→ to work。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U4' AND code='r3u4.01'), 'Astronauts collect dirty water so as ____ it for later use.', 'recycling', 'recycled', 'to recycle', 'recycle', 'C', 'so as to do 表目的 → to recycle。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U4' AND code='r3u4.01'), 'They stuck everything down in order ____ things floating off.', 'stopping', 'stopped', 'stop', 'to stop', 'D', 'in order to do 表目的 → to stop。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U4' AND code='r3u4.01'), 'Voyager 1 was launched ____ deep space far from Earth.', 'to study', 'studying', 'studied', 'study', 'A', '表目的''为了研究''→ to study。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U4' AND code='r3u4.01'), 'He trained for years ____ a fighter pilot before joining the programme.', 'becoming', 'to become', 'become', 'becomes', 'B', '表目的''为了成为''→ to become。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U4' AND code='r3u4.01'), 'China sent Chang''e 4 to the moon so as ____ the far side.', 'explored', 'exploring', 'to explore', 'explore', 'C', 'so as to do 表目的 → to explore。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U4' AND code='r3u4.01'), 'Astronauts exercise every day in order ____ healthy in space.', 'staying', 'stayed', 'stay', 'to stay', 'D', 'in order to do 表目的 → to stay。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U4' AND code='r3u4.01'), 'Tianzhou 1 was sent up ____ with the space lab.', 'to dock', 'docking', 'docked', 'dock', 'A', '表目的''为了对接''→ to dock。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U4' AND code='r3u4.01'), 'Scientists are growing crops in space ____ astronauts enough food.', 'giving', 'to give', 'given', 'give', 'B', '表目的''为了给''→ to give。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U4' AND code='r3u4.01'), 'We must save resources so as ____ them from running out.', 'prevented', 'preventing', 'to prevent', 'prevent', 'C', 'so as to do 表目的 → to prevent。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U4' AND code='r3u4.01'), 'He stayed up late ____ the report on the space mission.', 'finishing', 'finished', 'finish', 'to finish', 'D', '表目的''为了完成''→ to finish。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U4' AND code='r3u4.01'), 'Satellites were placed in orbit ____ weather patterns on Earth.', 'to record', 'recording', 'recorded', 'record', 'A', '表目的''为了记录''→ to record。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U4' AND code='r3u4.01'), 'Engineers checked the rocket carefully in order ____ any accidents.', 'avoiding', 'to avoid', 'avoided', 'avoid', 'B', 'in order to do 表目的 → to avoid。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U4' AND code='r3u4.01'), 'The crew moved slowly during the spacewalk so as ____ their bodies under control.', 'kept', 'keeping', 'to keep', 'keep', 'C', 'so as to do 表目的 → to keep。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U4' AND code='r3u4.01'), 'Many countries spend billions ____ the secrets of the universe.', 'finding', 'found', 'find', 'to find', 'D', '表目的''为了找出''→ to find。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U4' AND code='r3u4.01'), 'She studied physics hard ____ a place in the space programme.', 'to win', 'winning', 'won', 'win', 'A', '表目的''为了赢得''→ to win。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U4' AND code='r3u4.01'), 'The team built a new lab in order ____ life in space for longer.', 'supporting', 'to support', 'supported', 'support', 'B', 'in order to do 表目的 → to support。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U4' AND code='r3u4.01'), 'Astronauts attach themselves to the wall so as ____ around while they sleep.', 'not floating', 'floated', 'not to float', 'float', 'C', 'so as not to do 表目的(否定)→ not to float。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U4' AND code='r3u4.01'), 'They sent a rover to Mars ____ measurements of the surface.', 'making', 'made', 'make', 'to make', 'D', '表目的''为了进行(测量)''→ to make。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U4' AND code='r3u4.02'), 'Yuri Gagarin was the first person in the world ____ into space.', 'to go', 'going', 'gone', 'go', 'A', 'the first person to do 后置定语 → to go。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U4' AND code='r3u4.02'), 'Yuri Malenchenko became the first person ____ married in space.', 'getting', 'to get', 'got', 'get', 'B', 'the first person to do 后置定语 → to get。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U4' AND code='r3u4.02'), 'Astronauts always have a lot of work ____ on the station.', 'did', 'doing', 'to do', 'do', 'C', '名词 work 后接不定式作定语 → to do。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U4' AND code='r3u4.02'), 'Building rockets is the best way ____ Earth''s gravity.', 'escaping', 'escaped', 'escape', 'to escape', 'D', 'the best way to do 后置定语 → to escape。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U4' AND code='r3u4.02'), 'Neil Armstrong was the first man ____ on the moon.', 'to step', 'stepping', 'stepped', 'step', 'A', 'the first man to do 后置定语 → to step。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U4' AND code='r3u4.02'), 'In space, astronauts need something ____ to keep up their energy.', 'ate', 'to eat', 'eaten', 'eat', 'B', 'something to eat 后置定语 → to eat。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U4' AND code='r3u4.02'), 'China was the third country ____ humans into space on its own.', 'sending', 'sent', 'to send', 'send', 'C', 'the third country to do 后置定语 → to send。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U4' AND code='r3u4.02'), 'There is still much ____ about the far side of the moon.', 'learning', 'learned', 'learn', 'to learn', 'D', 'much (名词) 后接不定式作定语 → to learn。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U4' AND code='r3u4.02'), 'Laika was the first living thing ____ into orbit around Earth.', 'to go', 'going', 'gone', 'go', 'A', 'the first … thing to do 后置定语 → to go。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U4' AND code='r3u4.02'), 'Sleeping bags are the safest way ____ floating around at night.', 'avoiding', 'to avoid', 'avoided', 'avoid', 'B', 'the safest way to do 后置定语 → to avoid。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U4' AND code='r3u4.02'), 'Captain Brown had little free time ____ during his stay in space.', 'enjoyed', 'enjoying', 'to enjoy', 'enjoy', 'C', 'time 后接不定式作定语 → to enjoy。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U4' AND code='r3u4.02'), 'Yang Liwei was the first Chinese astronaut ____ Earth in a spacecraft.', 'orbiting', 'orbited', 'orbit', 'to orbit', 'D', 'the first … astronaut to do 后置定语 → to orbit。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U4' AND code='r3u4.02'), 'They were looking for a good place ____ the new space station.', 'to build', 'building', 'built', 'build', 'A', 'place to do 后置定语 → to build。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U4' AND code='r3u4.02'), 'On the long journey there is never enough water ____.', 'drinking', 'to drink', 'drunk', 'drink', 'B', 'water to drink 后置定语 → to drink。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U4' AND code='r3u4.02'), 'Shenzhou 7 carried the first Chinese astronaut ____ a spacewalk.', 'taking', 'taken', 'to take', 'take', 'C', 'the first … to do 后置定语 → to take。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U4' AND code='r3u4.02'), 'Mars may be the next planet ____ by human beings.', 'exploring', 'explore', 'exploring it', 'to explore', 'D', 'the next planet to explore 后置定语(被动含义由语境承担)→ to explore。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U4' AND code='r3u4.02'), 'There were many requirements ____ before he could join the programme.', 'to meet', 'meeting', 'met', 'meet', 'A', 'requirements to meet 后置定语 → to meet。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U4' AND code='r3u4.02'), 'Voyager 1 was the first spacecraft ____ deep space so far away.', 'reaching', 'to reach', 'reached', 'reach', 'B', 'the first spacecraft to do 后置定语 → to reach。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U4' AND code='r3u4.02'), 'Living on Mars may become the only choice ____ for humans one day.', 'leaving', 'left', 'to leave', 'leave', 'C', 'the only choice (left) to do 后置定语 → to leave。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U4' AND code='r3u4.02'), 'She felt proud to be the first member of her family ____ a scientist.', 'becoming', 'became', 'become', 'to become', 'D', 'the first member to do 后置定语 → to become。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U4' AND code='r3u4.03'), 'Some scientists were determined ____ humans realise their dream.', 'to help', 'helping', 'helped', 'help', 'A', 'be determined to do → to help。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U4' AND code='r3u4.03'), 'Captain Brown looked forward ____ his family after the mission. (avoid ''forward to'')', 'to see', 'to seeing', 'seen', 'see', 'B', 'look forward to + doing(to 是介词)→ to seeing。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U4' AND code='r3u4.03'), 'It is dangerous ____ out of orbit and back to Earth''s surface.', 'getting', 'got', 'to get', 'get', 'C', 'It is + adj. + to do 真主语 → to get。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U4' AND code='r3u4.03'), 'The captain told the new crew member ____ his seatbelt at once.', 'fastening', 'fastened', 'fasten', 'to fasten', 'D', 'tell sb to do 作宾补 → to fasten。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U4' AND code='r3u4.03'), 'Mr Yang always hoped ____ an astronaut one day.', 'to become', 'becoming', 'become', 'becomes', 'A', 'hope to do → to become。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U4' AND code='r3u4.03'), 'Astronauts can''t avoid ____ around when there is no gravity.', 'to float', 'floating', 'floated', 'float', 'B', 'avoid + doing(不接 to do)→ floating。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U4' AND code='r3u4.03'), 'Mission Control wants every astronaut ____ the safety rules carefully.', 'following', 'followed', 'to follow', 'follow', 'C', 'want sb to do 作宾补 → to follow。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U4' AND code='r3u4.03'), 'The team kept ____ until the spacecraft finally docked.', 'to try', 'tried', 'try', 'trying', 'D', 'keep + doing(不接 to do)→ trying。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U4' AND code='r3u4.03'), 'The space agency decided ____ a rover to the far side of the moon.', 'to send', 'sending', 'sent', 'send', 'A', 'decide to do → to send。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U4' AND code='r3u4.03'), 'Living in space for months means ____ your muscles every day.', 'to exercise', 'exercising', 'exercised', 'exercise', 'B', 'mean doing 意味着做某事 → exercising。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U4' AND code='r3u4.03'), 'The rules do not allow anyone ____ the station without a spacesuit.', 'leaving', 'left', 'to leave', 'leave', 'C', 'allow sb to do 作宾补 → to leave。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U4' AND code='r3u4.03'), 'After the long mission, he enjoyed ____ at the blue Earth below.', 'to look', 'looked', 'look', 'looking', 'D', 'enjoy + doing(不接 to do)→ looking。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U4' AND code='r3u4.03'), 'It is not easy ____ people to planets beyond the solar system.', 'to send', 'sending', 'sent', 'send', 'A', 'It is + adj. + to do 真主语 → to send。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U4' AND code='r3u4.03'), 'The doctor suggested ____ regularly to keep the muscles strong.', 'to exercise', 'exercising', 'exercised', 'exercise', 'B', 'suggest + doing(不接 to do)→ exercising。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U4' AND code='r3u4.03'), 'The captain asked the crew ____ enough food for the long journey.', 'storing', 'stored', 'to store', 'store', 'C', 'ask sb to do 作宾补 → to store。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U4' AND code='r3u4.03'), 'We can''t risk ____ all our oxygen so early in the mission.', 'to lose', 'lost', 'lose', 'losing', 'D', 'risk + doing(不接 to do)→ losing。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U4' AND code='r3u4.03'), 'The crew needs ____ the data back to Earth as soon as possible.', 'to transmit', 'transmitting', 'transmitted', 'transmit', 'A', 'need to do → to transmit。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U4' AND code='r3u4.03'), 'Scientists are busy ____ a way to travel faster through space.', 'to find', 'finding', 'found', 'find', 'B', 'be busy + doing 忙于做 → finding。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U4' AND code='r3u4.03'), 'Houston warned the astronauts not ____ their oxygen too quickly.', 'using', 'used', 'to use', 'use', 'C', 'warn sb not to do 作宾补(否定)→ not to use。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U4' AND code='r3u4.03'), 'It is important ____ astronauts both mentally and physically.', 'preparing', 'prepared', 'prepare', 'to prepare', 'D', 'It is + adj. + to do 真主语 → to prepare。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'Reaching for the Stars', 'Looking up at the stars, people have always wanted to learn more about space. Before the middle of the last century, most people felt that travelling into space was an impossible dream. However, some scientists were determined to make that dream come true. After many experiments, they finally built rockets that were powerful enough to escape Earth''s gravity. On 4 October 1957, the satellite Sputnik 1 was launched and went around our planet for the very first time. Less than four years later, on 12 April 1961, Yuri Gagarin became the first person in the whole world to go into space. These early steps were small, but each one pushed the door to the universe a little wider open. They showed everyone that the sky above us was no longer a wall, but a road waiting to be explored by brave and clever people.', '说明·太空探索的起步', 144, '[{"q":"How did most people feel about space travel before the mid-20th century?","answer":"A","options":["They thought it could never be done.","They were sure it was already easy.","They had no interest in the stars.","They believed it was cheap and safe."],"explanation":"原文 ''travelling into space was an impossible dream'' 的转述。"},{"q":"What did the rockets finally allow scientists to do?","answer":"B","options":["Stop all their experiments.","Break free from Earth''s pull.","Land directly on the sun.","Avoid using any satellites."],"explanation":"原文 ''powerful enough to escape Earth''s gravity'' 的转述。"},{"q":"What does the writer say about the early steps in space?","answer":"A","options":["Each one opened the way to the universe wider.","They were a waste of money.","They were quickly forgotten.","They proved space could not be reached."],"explanation":"末段 ''each one pushed the door to the universe a little wider open'' 的转述。"}]'::jsonb, '[{"word":"satellite","cn":"卫星"},{"word":"gravity","cn":"重力"},{"word":"launch","cn":"发射"}]'::jsonb, 2, 'required3', 'U4');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'A Day in the Life of an Astronaut', 'Life on a space station is very different from life at home. Because there is almost no gravity, everything floats, so astronauts must stick their tools and even their food to the wall. When it is time to eat, they often warm their meals and hold the packets carefully, or the food will drift away. Keeping clean is not easy either; instead of a normal shower, they use a little water and a wet towel to wash. To stay healthy, they exercise every single day, since their muscles and bones grow weak without gravity to work against. At bedtime, they climb into sleeping bags that are tied to the wall, so they will not float around in the dark. During their free time, many astronauts simply look out of the window. Watching the blue Earth turn quietly below them is, they say, the most beautiful sight of all.', '记叙·宇航员的太空生活', 148, '[{"q":"Why must astronauts stick their tools to the wall?","answer":"B","options":["Because the tools are very heavy.","Because there is little gravity and things float.","Because the walls are too cold.","Because the station has no shelves."],"explanation":"原文 ''almost no gravity, everything floats'' 的转述。"},{"q":"How do astronauts keep clean in space?","answer":"C","options":["They take a long hot shower.","They swim in a small pool.","They wash with a damp cloth and very little water.","They do not wash at all."],"explanation":"原文 ''a little water and a wet towel to wash'' 的转述。"},{"q":"Why do astronauts exercise every day?","answer":"D","options":["They have nothing else to do.","The captain forces them to.","Exercise helps them eat less.","Their muscles and bones become weak in space."],"explanation":"原文 ''muscles and bones grow weak without gravity'' 的转述。"}]'::jsonb, '[{"word":"float","cn":"漂浮"},{"word":"muscle","cn":"肌肉"},{"word":"gravity","cn":"重力"}]'::jsonb, 2, 'required3', 'U4');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'China''s Journey to the Stars', 'China''s space programme began later than those of Russia and the United States, yet it has made great progress in a short time. In 2003, Yang Liwei orbited Earth in the Shenzhou 5 spacecraft, and China became the third country able to send people into space on its own. Soon afterwards, Shenzhou 6 and 7 carried more astronauts, and one of them completed the first Chinese spacewalk. China then sent a small rover called Jade Rabbit to study the surface of the moon. Later, the Tiangong 2 space lab was launched, and Tianzhou 1 was sent up to dock with it. This step showed the world that China was steadily building towards a space station of its own. More recently, China sent Chang''e 4 to the far side of the moon, a place no country had reached before, to make new measurements and discoveries. Step by step, China keeps moving deeper into space.', '说明·中国航天的进步', 153, '[{"q":"What did China achieve in 2003?","answer":"A","options":["It became the third nation able to launch humans skyward on its own.","It built the first space station.","It landed the first person on the moon.","It launched its very first satellite."],"explanation":"原文 ''the third country able to send people into space on its own'' 的转述。"},{"q":"What was special about the Chang''e 4 mission?","answer":"B","options":["It carried the first Chinese astronaut.","It explored the moon''s far hemisphere, which no nation had visited.","It returned soil from the sun.","It docked with a foreign space lab."],"explanation":"原文 ''the far side of the moon, a place no country had reached before'' 的转述。"},{"q":"What does the docking of Tianzhou 1 show?","answer":"C","options":["China had given up space travel.","China only copied other countries.","China was working towards its own space station.","China stopped after Shenzhou 7."],"explanation":"原文 ''steadily building towards a space station of its own'' 的转述。"}]'::jsonb, '[{"word":"orbit","cn":"环绕运行"},{"word":"dock","cn":"对接"},{"word":"independently","cn":"独立地"}]'::jsonb, 2, 'required3', 'U4');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'The Hard Road to Mars', 'Sending people to Mars sounds exciting, but it is far from easy. The first problem is distance. Using the technology we have today, a return trip to the red planet would take more than two years. During such a long journey, the crew would need enough food, water and oxygen, and storing all of these is a serious challenge. There is also the danger of weightlessness, which slowly makes human muscles and bones weaker the longer people stay in space. On top of that, Mars is a cold and lonely world with thin air, so any small mistake could be fatal. Even so, scientists refuse to give up. They are testing new ways to grow crops in space and to recycle water, hoping these ideas will one day make the trip possible. Many believe that, sooner or later, the first human footprints will appear in the red dust of Mars.', '说明·飞往火星的难题', 150, '[{"q":"Why does the writer say a trip to Mars is difficult?","answer":"D","options":["Because Mars is too hot to land on.","Because rockets cannot leave Earth.","Because no one wants to go.","Because the long distance makes the journey take over two years."],"explanation":"原文 ''a return trip … would take more than two years'' 的转述。"},{"q":"What problem does long-term weightlessness cause?","answer":"A","options":["It slowly weakens human muscles and bones.","It makes the spacecraft heavier.","It speeds up the journey.","It uses up all the fuel."],"explanation":"原文 ''makes human muscles and bones weaker'' 的转述。"},{"q":"How are scientists responding to these difficulties?","answer":"B","options":["They have cancelled all Mars plans.","They are testing ways to grow food and recycle water.","They are sending only robots forever.","They are ignoring the problems."],"explanation":"原文 ''testing new ways to grow crops … recycle water'' 的转述。"}]'::jsonb, '[{"word":"oxygen","cn":"氧气"},{"word":"fatal","cn":"致命的"},{"word":"recycle","cn":"回收利用"}]'::jsonb, 2, 'required3', 'U4');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'Why Bother with Space?', 'Some people argue that exploring space is a waste of time and money. They say we should feed the world''s poor and solve problems like pollution before spending billions on distant planets. Yet others believe this is a shallow view that misses how much space work helps us here on Earth. Take the satellites that now circle our planet. Many of them record information about land and weather, and this data is sent to scientists who then advise farmers how to grow more food. Space research has also improved everyday technology. Better heart monitors, stronger materials and even smartphone cameras all grew out of tools first made for space. Finally, photographs of Earth from far away made people realise that our resources are limited and must be shared with care. In this way, looking outwards into space has, surprisingly, taught us to look more wisely at our own home.', '议论·为何探索太空', 149, '[{"q":"What do people against space exploration believe?","answer":"C","options":["Space travel is perfectly safe.","Farmers do not need any help.","Money should first go to problems on Earth.","Satellites are useless toys."],"explanation":"原文 ''feed the world''s poor and solve problems … before spending billions'' 的转述。"},{"q":"How do weather satellites help farmers?","answer":"D","options":["They water the fields directly.","They replace all farm workers.","They sell crops for higher prices.","They send data that helps scientists advise farmers."],"explanation":"原文 ''this data is sent to scientists who then advise farmers'' 的转述。"},{"q":"What did photographs of Earth from space make people realise?","answer":"A","options":["That what the planet offers us is finite and needs careful sharing.","That Earth is very large.","That space is empty.","That farming is unnecessary."],"explanation":"原文 ''resources are limited and must be shared with care'' 的转述。"}]'::jsonb, '[{"word":"shallow","cn":"肤浅的"},{"word":"monitor","cn":"监测仪"},{"word":"resource","cn":"资源"}]'::jsonb, 2, 'required3', 'U4');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'Becoming an Astronaut', 'Becoming an astronaut is one of the hardest jobs in the world to win. First of all, you must be intelligent enough to earn a related college degree, often in science or engineering. After that comes years of flying experience; in China, for example, candidates once needed about a thousand hours in the air as pilots. Health matters too, for an astronaut must be strong, calm and free of serious illness. Yang Liwei was chosen from among many fighter pilots, and only a small number passed every test. Once selected, the work has only begun. Future astronauts learn how to use complex space equipment, and they also do a great deal of mental and physical training so as to stay calm under pressure. The selection procedure is long and tiring, and most people who apply are turned away. Yet for those who succeed, the chance to see Earth from space makes every hard day worth it.', '说明·如何成为宇航员', 156, '[{"q":"What is the first requirement mentioned for becoming an astronaut?","answer":"B","options":["Owning an aeroplane.","Being clever enough to get a related college degree.","Living near a space centre.","Speaking many languages."],"explanation":"原文 ''intelligent enough to earn a related college degree'' 的转述。"},{"q":"Why must astronauts do mental and physical training?","answer":"C","options":["To make them taller.","To save the agency money.","To help them stay calm under pressure.","To replace flying experience."],"explanation":"原文 ''mental and physical training so as to stay calm under pressure'' 的转述。"},{"q":"What does the passage say about most people who apply?","answer":"D","options":["They are all accepted.","They never finish college.","They become pilots instead.","Most of them are turned away."],"explanation":"原文 ''most people who apply are turned away'' 的转述。"}]'::jsonb, '[{"word":"intelligent","cn":"聪明的"},{"word":"procedure","cn":"程序"},{"word":"mental","cn":"心理的"}]'::jsonb, 2, 'required3', 'U4');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required3', 'U4', 'My First Spacewalk', 'I will never forget my first spacewalk. Before I left the spacecraft, I had to put on a heavy (1)____ to protect me from the cold. My captain reminded me to (2)____ myself to the station with a strong rope, or I would float away into the dark. When the door opened, I moved very (3)____ so as to keep my body under control. Outside, there was no air to (4)____, so the suit gave me oxygen. The Earth turned quietly below me, and I felt both (5)____ and a little afraid. My job was to (6)____ a broken part of the station. Working without gravity was not (7)____, because my tools kept trying to drift away from my hands. After two hours, I was (8)____ but happy. As I climbed back inside, I (9)____ that this was a dream I had had since I was a child. That spacewalk was the proudest (10)____ of my whole life.', 158, 2, '[{"q":"1","answer":"A","options":["spacesuit","machine","ticket","garden"],"explanation":"穿 spacesuit 太空服。"},{"q":"2","answer":"B","options":["sell","tie","throw","hide"],"explanation":"tie myself to 把自己系到。"},{"q":"3","answer":"C","options":["loudly","cheaply","slowly","angrily"],"explanation":"move slowly 缓慢移动。"},{"q":"4","answer":"D","options":["sell","buy","draw","breathe"],"explanation":"no air to breathe 没有空气可呼吸。"},{"q":"5","answer":"A","options":["excited","bored","asleep","hungry"],"explanation":"felt excited 感到兴奋。"},{"q":"6","answer":"B","options":["lose","repair","forget","throw"],"explanation":"repair a broken part 修理坏掉的部件。"},{"q":"7","answer":"C","options":["heavy","loud","easy","wet"],"explanation":"not easy 不容易。"},{"q":"8","answer":"D","options":["rich","early","late","tired"],"explanation":"tired but happy 累但开心。"},{"q":"9","answer":"A","options":["realised","lost","sold","feared"],"explanation":"realised that 意识到。"},{"q":"10","answer":"B","options":["price","moment","noise","machine"],"explanation":"the proudest moment 最自豪的时刻。"}]'::jsonb, 1);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required3', 'U4', 'Breakfast Without Gravity', 'Eating breakfast in space is stranger than you might (1)____. Because there is almost no gravity, the food does not stay on the plate but tries to (2)____ into the air. So astronauts keep their meals in small bags and warm them in a special (3)____. They must hold the bag (4)____, or tiny pieces of food will drift around the room. Drinking is also tricky, since water forms little balls that float away if you are not (5)____. There are no open cups; instead, astronauts drink through a tube. Even the salt and pepper come as a (6)____ so that they will not fly everywhere. After eating, the crew clean up very carefully, because a single crumb left behind could (7)____ a machine if it floats into the wrong place. It may sound like hard work, but the astronauts soon get (8)____ to it. Many of them say that, after a few weeks, this odd way of eating begins to feel almost (9)____. And nothing on Earth, they add, beats the (10)____ of the planet you can watch through the window while you eat.', 185, 2, '[{"q":"1","answer":"C","options":["sell","lose","think","throw"],"explanation":"than you might think 你能想到的。"},{"q":"2","answer":"D","options":["sink","fall","land","float"],"explanation":"float into the air 漂到空中。"},{"q":"3","answer":"A","options":["microwave","garden","market","river"],"explanation":"warm in a microwave 用微波炉加热。"},{"q":"4","answer":"B","options":["loudly","tightly","cheaply","angrily"],"explanation":"hold tightly 紧紧抓住。"},{"q":"5","answer":"C","options":["rich","late","careful","asleep"],"explanation":"not careful 不小心。"},{"q":"6","answer":"D","options":["noise","song","price","liquid"],"explanation":"come as a liquid 做成液体形式。"},{"q":"7","answer":"A","options":["damage","clean","feed","sell"],"explanation":"damage a machine 损坏机器。"},{"q":"8","answer":"B","options":["angry","used","afraid","sorry"],"explanation":"get used to 习惯。"},{"q":"9","answer":"C","options":["broken","empty","normal","wet"],"explanation":"feel normal 感觉正常。"},{"q":"10","answer":"D","options":["price","noise","machine","view"],"explanation":"the view of the planet 行星的景色。"}]'::jsonb, 2);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required3', 'U4', 'Eyes in the Sky', 'High above our heads, thousands of satellites quietly (1)____ around the Earth. Many people think they are useful only for phones, but they do far (2)____ than that. Some satellites watch the weather and (3)____ pictures of storms long before they reach land. This early warning gives families enough (4)____ to move to safety. Other satellites study the land and send (5)____ about soil and rain back to scientists. After careful study, the scientists can (6)____ farmers when and where to plant their crops. In this way, tools first built for space now help us grow (7)____ food for a growing world. Satellites also carry signals for television and the internet, (8)____ people across the whole globe in seconds. It is amazing to think that machines so far away can change daily life so (9)____. The next time you check the weather on your phone, remember that an eye in the sky is quietly (10)____ over you.', 157, 2, '[{"q":"1","answer":"A","options":["move","sink","fall","stop"],"explanation":"move around the Earth 绕地球运行。"},{"q":"2","answer":"B","options":["less","more","worse","fewer"],"explanation":"do far more 做得多得多。"},{"q":"3","answer":"C","options":["eat","sell","send","hide"],"explanation":"send pictures 发送图像。"},{"q":"4","answer":"D","options":["money","noise","salt","time"],"explanation":"enough time 足够时间。"},{"q":"5","answer":"A","options":["data","songs","prices","games"],"explanation":"send data 发送数据。"},{"q":"6","answer":"B","options":["forget","advise","sell","lose"],"explanation":"advise farmers 建议农民。"},{"q":"7","answer":"C","options":["less","worse","more","fewer"],"explanation":"grow more food 种更多粮食。"},{"q":"8","answer":"D","options":["losing","breaking","selling","connecting"],"explanation":"connecting people 把人们连接起来。"},{"q":"9","answer":"A","options":["greatly","rarely","hardly","never"],"explanation":"change life greatly 极大地改变生活。"},{"q":"10","answer":"B","options":["sleeping","watching","sitting","crying"],"explanation":"watching over you 守护着你。"}]'::jsonb, 3);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required3', 'U4', 'The Problem of Space Junk', 'Every time a rocket is launched, it can leave small pieces of metal behind in space. Over the years, these pieces have (1)____ into a huge cloud of rubbish that we call space junk. Although each piece may be (2)____, it travels so fast that it can (3)____ a working satellite to pieces. Scientists must carefully (4)____ where all this junk is, so that new spacecraft can avoid it. If they fail, a single (5)____ could destroy years of work in a moment. The problem keeps growing as more and more countries (6)____ rockets into orbit. Some teams are now (7)____ clever machines that could one day catch the junk and pull it down to burn up safely. Cleaning up space will not be (8)____, but it is important for the future. After all, we do not want the road to the stars to become (9)____ with our own rubbish. Keeping space (10)____ is a job for the whole world to share.', 162, 2, '[{"q":"1","answer":"C","options":["fallen","sunk","grown","landed"],"explanation":"grown into 发展成。"},{"q":"2","answer":"D","options":["loud","wet","warm","small"],"explanation":"may be small 可能很小。"},{"q":"3","answer":"A","options":["break","feed","clean","sell"],"explanation":"break a satellite to pieces 把卫星撞碎。"},{"q":"4","answer":"B","options":["forget","track","lose","hide"],"explanation":"track where the junk is 追踪垃圾位置。"},{"q":"5","answer":"C","options":["song","price","crash","garden"],"explanation":"a single crash 一次撞击。"},{"q":"6","answer":"D","options":["eat","sell","drop","send"],"explanation":"send rockets 发射火箭。"},{"q":"7","answer":"A","options":["designing","losing","breaking","selling"],"explanation":"designing machines 设计机器。"},{"q":"8","answer":"B","options":["wet","easy","loud","rich"],"explanation":"not be easy 不容易。"},{"q":"9","answer":"C","options":["clean","empty","blocked","cheap"],"explanation":"blocked with rubbish 被垃圾堵塞。"},{"q":"10","answer":"D","options":["dark","loud","heavy","clean"],"explanation":"keep space clean 保持太空清洁。"}]'::jsonb, 4);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required3', 'U4', 'Sending a Rover to the Moon', 'When a country wants to study the moon, it often sends a small robot car called a (1)____. This clever machine can travel across the surface where no human has yet (2)____ a foot. Before it leaves Earth, engineers test it again and again so as to make (3)____ it will work far away. After a long journey, the rover lands gently and slowly (4)____ to explore. Its cameras take pictures, while other tools (5)____ the rocks and soil. All this information is then (6)____ back to scientists waiting on Earth. Because the moon is so far, the signals take time to (7)____, and the team must be patient. Sometimes the rover finds something nobody (8)____, and everyone in the control room cheers. A good rover can keep working for (9)____, long after people expected it to stop. Step by step, these brave little machines help us learn the (10)____ of a world we cannot yet visit ourselves.', 158, 2, '[{"q":"1","answer":"A","options":["rover","garden","market","river"],"explanation":"a rover 月球车。"},{"q":"2","answer":"B","options":["sold","set","lost","eaten"],"explanation":"set a foot 踏足。"},{"q":"3","answer":"C","options":["noise","price","sure","song"],"explanation":"make sure 确保。"},{"q":"4","answer":"D","options":["sleeps","stops","ends","begins"],"explanation":"begins to explore 开始探索。"},{"q":"5","answer":"A","options":["study","sell","lose","hide"],"explanation":"study the rocks 研究岩石。"},{"q":"6","answer":"B","options":["eaten","sent","sold","thrown"],"explanation":"sent back 传回。"},{"q":"7","answer":"C","options":["sell","eat","arrive","hide"],"explanation":"signals take time to arrive 信号需要时间到达。"},{"q":"8","answer":"D","options":["lost","sold","broke","expected"],"explanation":"nobody expected 没人预料到。"},{"q":"9","answer":"A","options":["years","minutes","seconds","metres"],"explanation":"for years 持续多年。"},{"q":"10","answer":"B","options":["price","secrets","noise","machines"],"explanation":"learn the secrets 了解秘密。"}]'::jsonb, 5);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required3', 'U4', 'A Childhood Dream', 'When I was young, I often lay on the grass at night and looked up at the (1)____. I would point to the stars and tell my mother that one day I would (2)____ into space. She smiled and said that if I worked hard, my dream might come (3)____. So I studied science with all my (4)____, even when the lessons were difficult. At school, I read every book about rockets and planets that I could (5)____. My friends thought space was boring, but to me it was the most (6)____ subject of all. Years later, I joined a space programme and began the long, hard (7)____ of training to become an astronaut. There were many days when I felt (8)____ and wanted to give up, yet I always remembered that little child on the grass. Now, when I look down at Earth through the window, I feel deeply (9)____. Dreams, I have learned, are worth all the (10)____ it takes to reach them.', 165, 2, '[{"q":"1","answer":"C","options":["floor","wall","sky","table"],"explanation":"looked up at the sky 仰望天空。"},{"q":"2","answer":"D","options":["sink","fall","sell","travel"],"explanation":"travel into space 进入太空。"},{"q":"3","answer":"A","options":["true","off","down","back"],"explanation":"come true 成真。"},{"q":"4","answer":"B","options":["price","heart","noise","machine"],"explanation":"with all my heart 全心全意。"},{"q":"5","answer":"C","options":["sell","lose","find","throw"],"explanation":"books I could find 能找到的书。"},{"q":"6","answer":"D","options":["boring","useless","ugly","exciting"],"explanation":"the most exciting subject 最激动人心的学科。"},{"q":"7","answer":"A","options":["road","holiday","game","joke"],"explanation":"the long hard road 漫长艰难的路。"},{"q":"8","answer":"B","options":["rich","tired","early","late"],"explanation":"felt tired 感到疲惫。"},{"q":"9","answer":"C","options":["angry","afraid","proud","bored"],"explanation":"feel proud 感到自豪。"},{"q":"10","answer":"D","options":["price","noise","song","effort"],"explanation":"worth all the effort 值得所有努力。"}]'::jsonb, 6);
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U4 听力·对话 Meeting a Real Astronaut', '必修三 U4 · dialogue', 3, 'Max: Captain Brown, thank you for coming. What did you usually wear inside the station?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U4 听力·短文 A Day in Space', '必修三 U4 · passage', 2, 'On a space station, every day begins by tying yourself out of the sleeping bag.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U4 听力·对话 Interviewing China''s First Astronaut', '必修三 U4 · dialogue', 3, 'Host: Mr Yang, when did you first dream of going into space?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U4 听力·短文 The Journey to Mars', '必修三 U4 · passage', 2, 'Many scientists dream of one day sending people to Mars.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U4 听力·对话 At the Space Camp', '必修三 U4 · dialogue', 3, 'Anna: I''m so excited! We''re going to meet a real astronaut at the space camp.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U4 听力·短文 Advice for Future Astronauts', '必修三 U4 · passage', 2, 'If you want to become an astronaut one day, here is some simple advice.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit) VALUES (10, 'Write an argumentative essay about the value of space exploration(写一篇关于太空探索价值的议论文)', 'Is Space Exploration Worth the Cost?', '假设你叫李华,学校英语报正在征稿,主题是''太空探索值得吗?''。请用英语写一篇约100词的议论文,内容包括:① 提出你的观点(太空探索值得/不值得);② 给出两到三条理由(如卫星帮助农业、推动科技、寻找新家园);③ 在结尾重申你的观点。注意:用不定式表目的(to do / in order to / so as to)等结构。', 'Suppose you are Li Hua. Your school''s English newspaper is collecting articles on the topic ''Is space exploration worth it?''. Write an argumentative essay (about 100 words) that: 1) states your opinion (space exploration is / is not worth it); 2) gives two or three reasons (e.g. satellites help farming, space research drives technology, the search for a new home); 3) restates your opinion at the end. Try to use to-infinitives of purpose (to do / in order to / so as to).', '["提出观点(In my opinion, exploring space is well worth it.)","理由一·卫星与农业(Satellites collect data so as to help farmers grow more food.)","理由二·科技进步(Space research drives technology to improve daily life.)","结尾重申观点(For these reasons, I firmly believe space exploration is worthwhile.)"]'::jsonb, 70, 100, 'Countries around the globe spend billions on space missions, and some people think this is a waste. In my opinion, however, exploring space is well worth it. Firstly, satellites circle the Earth to collect data on weather and land, which helps farmers grow more food. Secondly, space research drives technology forward; many useful products, from heart monitors to smartphone cameras, were first made for space. Finally, scientists explore other planets so as to find a possible new home, because our resources are limited. For these reasons, I firmly believe that space exploration is not a waste, but a wise investment in our future.', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["In my opinion, exploring space is well worth it.","Satellites circle the Earth to collect data so as to help farmers grow more food.","Many useful products, from heart monitors to smartphone cameras, were first made for space.","Scientists explore other planets to find a possible new home, because our resources are limited."]'::jsonb, '[{"wrong":"We explore space for find a new home.","correct":"We explore space to find a new home.","note":"表目的用不定式 to do,不用 for + do。"},{"wrong":"Satellites are sent up for collecting data.","correct":"Satellites are sent up to collect data.","note":"表目的更自然用 to do;for doing 表用途、口气不同。"},{"wrong":"It is worth to explore space.","correct":"It is worth exploring space.","note":"be worth + doing 是固定结构,不接 to do。"}]'::jsonb, '【太空探索议论文结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content) VALUES (10, 'required3', 'U4', '{"title":"不定式 to do 三大用法速查(目的状语 / 后置定语 / 宾语·宾补·主语)","intro":"不定式 to do 既能表''为了……''(目的),又能放在名词后表''要做的''(定语),还能作宾语、宾补和主语。口诀:表目的用 to do;名词后修饰用 to do;跟在 want/ask/It is… 后看搭配。","table":{"headers":["用法","标志 / 例句"],"rows":[["目的状语","to do = in order to do = so as to do:They make vehicles to carry people into space."],["后置定语","名词 + to do:the first person to go into space;a lot of work to do;something to eat"],["作宾语","want/decide/hope/need + to do:He hoped to become an astronaut."],["作宾补","ask/tell/allow/want sb to do:The captain told us to fasten our seatbelts."],["作主语","It is + adj. + to do:It is dangerous to get out of orbit."]]},"specialRules":[{"rule":"表目的:to do / in order to do / so as to do 三者可互换;否定用 not to do / so as not to do","mark":"so as not to float around √"},{"rule":"the first/second/last/only + 名词 + 后,几乎必用不定式","mark":"the first person to get married in space"},{"rule":"avoid / enjoy / keep / suggest / mean(意味着)/ be busy / look forward to 后接 doing,不接 to do","mark":"avoid floating √ / avoid to float ×"},{"rule":"It is + adj. + to do 中 It 是形式主语,真主语是后面的 to do","mark":"It is hard to send people to Mars."}],"why":["不定式 to do 自带''未来、要去做''的意味,所以最适合表示''目的''和''名词后将要做的动作'';而 doing 强调正在进行或一般状态,搭配由前面的动词决定。"],"gaokaoPoints":["语法填空高频:给动词原形,判断填 to do(目的/定语)还是 doing(avoid/enjoy/keep 等后)。","to do 与 doing 对照题:看前面的谓语动词搭配(want to do vs avoid doing)。","in order to / so as to 表目的,so as to 一般不放句首。"],"examVsReal":[{"exam":"He stayed up late in order to finish the report.（考试/书面）","real":"He stayed up late to finish the report.","note":"口语里常直接用 to do,in order to 偏正式"},{"exam":"She was the first person to arrive.（考试）","real":"She was the first to arrive / the first one there.","note":"口语可省略名词,意思一样"}]}'::jsonb);
